    vec2: "f2",
    vec3: "f3",
    vec4: "f4",
    ivec2: "i2",
    ivec3: "i3",
    ivec4: "i4",
    uvec2: "u2",
    uvec3: "u3",
    uvec4: "u4",
    bvec2: "b2",
